typedef struct { float x, y, z; } vec3;
typedef struct { vec3 origin, dir; } ray;
typedef struct { float t; vec3 point, normal; int hit; } hit_record;

vec3 v_add(vec3 a, vec3 b) { return (vec3){a.x+b.x, a.y+b.y, a.z+b.z}; }
vec3 v_sub(vec3 a, vec3 b) { return (vec3){a.x-b.x, a.y-b.y, a.z-b.z}; }
vec3 v_mul(vec3 a, float t) { return (vec3){a.x*t, a.y*t, a.z*t}; }
float v_dot(vec3 a, vec3 b) { return a.x*b.x + a.y*b.y + a.z*b.z; }
vec3 v_cross(vec3 a, vec3 b) { return (vec3){a.y*b.z-a.z*b.y, a.z*b.x-a.x*b.z, a.x*b.y-a.y*b.x}; }
float v_len(vec3 a) { return sqrtf(v_dot(a,a)); }
vec3 v_norm(vec3 a) { float l = v_len(a); return l > 0 ? v_mul(a, 1.0f/l) : a; }

ray ray_create(vec3 origin, vec3 dir) { return (ray){origin, v_norm(dir)}; }
vec3 ray_at(ray r, float t) { return v_add(r.origin, v_mul(r.dir, t)); }

int sphere_intersect(ray r, vec3 center, float radius, hit_record *rec) {
    vec3 oc = v_sub(r.origin, center);
    float a = v_dot(r.dir, r.dir);
    float b = 2.0f * v_dot(oc, r.dir);
    float c = v_dot(oc, oc) - radius*radius;
    float disc = b*b - 4*a*c;

    if (disc < 0) return 0;

    float sqrtd = sqrtf(disc);
    float t = (-b - sqrtd) / (2*a);
    if (t < 0.001f || t > 1e6f) {
        t = (-b + sqrtd) / (2*a);
        if (t < 0.001f || t > 1e6f) return 0;
    }

    rec->t = t;
    rec->point = ray_at(r, t);
    rec->normal = v_norm(v_sub(rec->point, center));
    rec->hit = 1;
    return 1;
}

vec3 trace(ray r, int depth) {
    if (depth > 50) return (vec3){0, 0, 0};

    hit_record best; best.hit = 0; best.t = 1e6f;

    vec3 spheres[] = {{0,0,-1}, {0,-100.5,-1}, {1,0,-1}, {-1,0,-1}};
    float radii[] = {0.5f, 100, 0.5f, 0.5f};

    for (int i = 0; i < 4; i++) {
        hit_record rec;
        if (sphere_intersect(r, spheres[i], radii[i], &rec) && rec.t < best.t) {
            best = rec;
        }
    }

    if (!best.hit) {
        float t = 0.5f * (r.dir.y + 1.0f);
        return v_add(v_mul((vec3){1,1,1}, 1.0f - t), v_mul((vec3){0.5f,0.7f,1}, t));
    }

    vec3 target = v_add(best.point, best.normal);
    ray scattered = ray_create(best.point, v_sub(target, best.point));
    vec3 col = trace(scattered, depth + 1);
    return v_mul(col, 0.5f);
}

